INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('bae8b306-423b-469c-87af-dfd7ad058758', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Filesystem Inspector', 'After mounting, create /mnt/data/test.txt with "hello". Run: lsblk -f | head -3. What filesystem type is shown for your loop device?', 100, '$2b$10$p0w6I.9Ol893LGvx9zRTgOGc6YVbr4uNvLco4NHo.xP7dbVlTKfq2' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('351e25d1-2222-42af-b106-5167497d59a3', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'LVM Creator', 'Create 2 loop devices (dd if=/dev/zero of=/tmp/disk1.img bs=1M count=50, same for disk2). Create PV: pvcreate /tmp/disk1.img /tmp/disk2.img. Run: pvdisplay | grep "PV Name" | wc -l. How many PVs?', 100, '$2b$10$xpgjxj/6Gc5yp4IVsN3R9eiUevv3rbkNPJ7txKmi9gT9v1tImcdpK' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('3d66ede5-b32c-418f-a567-2004bc93f701', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'VG Builder', 'Create volume group: vgcreate myvg /tmp/disk1.img /tmp/disk2.img. Run: vgdisplay myvg | grep "PE Size". What is the PE size?', 100, '$2b$10$dLkC3Sn0RBByLw6gr021ruYgSPwSfzZOMO410ooyCT0B3zsm3KXkK' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('4c0d26fe-a30a-4eed-803d-6159597ce366', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'LV Crafter', 'Create logical volume: lvcreate -L 30M -n mylv myvg. Run: lvdisplay /dev/myvg/mylv | grep "LV Size". What is the size?', 100, '$2b$10$5TV05p5M/GdkEz31lpAYQ.R9lED5Ccmvp0SIRupnKLFdNubNN7Md2' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0f00c048-9b79-4a19-b495-2dcb34b3fc9e', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'RAID Builder', 'Create RAID0: mdadm --create /dev/md0 --level=0 --raid-devices=2 /tmp/disk1.img /tmp/disk2.img 2>/dev/null; Run: cat /proc/mdstat | grep md0 | awk "{print $4}". What is the status?', 100, '$2b$10$CFOxfT.gJ/vErI3dK6rXq.8FC4hjAsXPjIN9Fn1BMM94hYm4qKf/W' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('78e1314b-a7ad-42b3-b82b-7e6e05635434', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Swap Creator', 'Create 50MB swap: dd if=/dev/zero of=/tmp/swap.img bs=1M count=50 && mkswap /tmp/swap.img && swapon /tmp/swap.img. Run: swapon --show | wc -l. How many swap devices (minus header)?', 100, '$2b$10$2qQlb4UHRAM7pdAaFLEBC.8gLVIrALvwGR5qnGyRkjdYMKQZwwtHW' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('2eef6021-8855-4bd4-aa92-2afe1a366e32', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'DF Detective', 'Run: df -h --output=source,size,used,avail,target | grep tmp | head -1. What is the mount point?', 75, '$2b$10$m6hbloMrnl20t5fRYxGRfORKVGxCCTNB0zBYtlQfHIMJPzIR9RgZq' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9203d26c-73c8-4997-9510-c67fd16a7030', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Fstab Editor', 'Add to /etc/fstab: /tmp/disk.img /mnt/data ext4 loop 0 0. Run: grep "/mnt/data" /etc/fstab | awk "{print $3}". What filesystem type is listed?', 100, '$2b$10$ziUMpBYK0kpD3/PNXQe1yuTc91QoDGd6qtFczPfUe5Qy7pEEMK28u' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('84927b6e-6661-4a4f-9dd8-93349c91d257', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Inode Counter', 'Run: df -i / | tail -1 | awk "{print $4}". How many free inodes?', 100, '$2b$10$Xef2uFbBWuSVUHvfIcmBi.Zn1QTUnuwP59PYcoQCyYrQI8i0PuvuO' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ef8c1bad-f0f6-491c-826d-54591b494e57', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Du Analyzer', 'Create files in /mnt/data (dd if=/dev/zero of=/mnt/data/bigfile bs=1M count=10). Run: du -sh /mnt/data | awk "{print $1}". What is the size?', 100, '$2b$10$qPXbuDq1EoFzHhqfB7d7XOCpZIW8OYRTkcll6ZxuxrlEZnGhVYkKm' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('e99314be-5326-491f-ace2-2407e9800189', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'UUID Finder', 'Run: blkid /dev/loop0 2>/dev/null | grep -o "UUID=\"[^ ]*\"" | head -1. What is the UUID format? (just answer "uuid" if you can see it)', 75, '$2b$10$GqJYJzM34gz8FTVxZEjqr.jh3fgLtlFRz0ZGk2AgMPNcYLBLljh4S' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('54a42e97-e84e-4d65-9262-a113a6cd9c52', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Fdisk Explorer', 'Run: fdisk -l /tmp/disk.img 2>/dev/null | head -5. What disk identifier type is shown?', 100, '$2b$10$G48orO0a9J9n6YQQr5h7mOXZb/gMLp/hJ02kLuAvZ0Tu5b7w1oCfO' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0700e8df-4afd-41d0-a49a-4ddd603114d4', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Cleanup Crew', 'Run: umount /mnt/data && losetup -D && vgremove -f myvg 2>/dev/null; echo "storage_done". What is the output?', 75, '$2b$10$qyTW7SDQZE869vePq//4nuj3KcNlKK0pLhMKMjxyKWFHs2lg.GIY2' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('e3d0073a-2e41-4b85-b923-cd2f1b8e628e', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Tar Crafter', 'Create /home/student/backup_data/ with 3 files (a.txt, b.txt, c.txt). Pack: tar czf /tmp/backup.tar.gz -C /home/student backup_data. Run: tar tzf /tmp/backup.tar.gz | wc -l. How many entries?', 75, '$2b$10$UWgha2TOJpcl14FuBcvQJe4Nes8eUZ5foTSDgSk4.5mfpbzpabQHu' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('00b42c01-f95a-4452-9913-91888afa2a46', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Cron Scheduler', 'Add cron job: echo "0 * * * * echo backup_ok > /tmp/cron_proof" | crontab -. Run: crontab -l | wc -l. How many cron entries?', 75, '$2b$10$IppGcbHLQnZOlQeQpem7XegVlz1l6s.0m02Thqfpf2WbzJuUDUvfm' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('2e830366-9801-4e1a-a29d-9fdcd0114efb', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Restore Tester', 'Create /tmp/restore_dir/. Extract backup: tar xzf /tmp/backup.tar.gz -C /tmp/restore_dir. Run: ls /tmp/restore_dir/backup_data/ | wc -l. How many files restored?', 100, '$2b$10$nJQXHt693hwruefB/X9b8ead5g5WdzsIKszSA95u7XToE9MeZeiyO' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d521dc23-35a9-4327-a749-94da0f418ab0', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Incremental Creator', 'Create new file d.txt. Create incremental: tar czf /tmp/incr.tar.gz -C /home/student/backup_data --newer=a.txt . Run: tar tzf /tmp/incr.tar.gz. What file is listed?', 100, '$2b$10$xEAYQLtNRdBS5KS31xJfJO4vaaaT0kGEYa1D5ioJTWJvwlGAxyFqq' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('3341dd0c-eea8-432a-a835-4bbf35b097bd', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'rsync Master', 'Create /tmp/src_dir/ and /tmp/dst_dir/. Create file in src. Run: rsync -av /tmp/src_dir/ /tmp/dst_dir/ && ls /tmp/dst_dir/. What file is synced?', 100, '$2b$10$bdR0cCNGWGK92blAbVlMoexVq6SOM.T0zXacka/RI.FDf19uv7cuC' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('99126168-3792-4824-9d27-5cb022236515', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Exclusion Expert', 'Create files: log.txt, data.csv, log2.txt. Run: tar czf /tmp/no_logs.tar.gz --exclude="log*" -C /home/student/backup_data . Run: tar tzf /tmp/no_logs.tar.gz | grep -c log. How many log files included?', 100, '$2b$10$QZckQh9u2U43V.rcg5nfXufaO7sDnf2AsjgYUamsRkZtpbdkmHVgO' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('dec83734-e685-48ab-abad-82b80da1745c', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Compression Pro', 'Compare: tar czf /tmp/gz.tar.gz -C /home/student/backup_data . vs tar cJf /tmp/xz.tar.xz -C /home/student/backup_data . Run: ls -la /tmp/gz.tar.gz /tmp/xz.tar.xz | awk "{print $5, $9}". Which is smaller?', 100, '$2b$10$fgugx2GT9bxLurhOZfi6TO3LsJZ1rRsH0d3cNM.EBqrs3YQTcM05O' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d03221dd-e78f-4037-902c-8319971116ee', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Verify Expert', 'Run: tar tzf /tmp/backup.tar.gz > /tmp/list.txt && md5sum /tmp/list.txt. What is the first 8 chars of the hash?', 100, '$2b$10$G332b3ntwCWnHm28nd.XpOZaHDUBC53QlEBiclwGuwCIn6XPDtGRS' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('1043ee9c-8c52-46d0-8bff-6e9d446d2664', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Docker Backup', 'Run: docker run -d --name db-backup alpine:3.18 sleep 300. Then: docker export db-backup > /tmp/container_backup.tar && wc -c /tmp/container_backup.tar. How many bytes (approximately)?', 100, '$2b$10$S3EZbEVi7GaAgzCEzJc3RezryDQBc7ttQQSAf0ww7Gq843FvTvvgi' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('00264466-d729-4548-872f-ae45dd0f13d3', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Cron Checker', 'Run: cat /var/spool/cron/crontabs/root 2>/dev/null | head -1. What is the cron schedule?', 75, '$2b$10$vf.yqxGH.Siubgd0gjbQjOx85IKVSL.QfJ0k6NnMnB3T1eNIdk3Fm' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('742e5836-dceb-49a0-8c05-234934a90fc7', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Diff Backup', 'Create /tmp/original/file.txt with "old". Copy to /tmp/backup_version/. Change original to "new". Run: diff /tmp/original/file.txt /tmp/backup_version/file.txt. What is shown?', 100, '$2b$10$fcfbhmxktnqu9FM4Df1FY.TCDD0Cyod85wsyNqvZoiwpIDHFGVSdW' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5055adf8-637e-4274-9594-f22394bc00ed', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Archive Inspector', 'Run: file /tmp/backup.tar.gz. What is the detected type?', 75, '$2b$10$tTsQdwj7MhVPlbhwrl9Ps.xXhdTbcBbEZhY71YxW/nDuk.XwLGhhu' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9bfacb21-2026-447d-b5c8-30c4ec22cb12', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Cleanup Script', 'Create /home/student/cleanup.sh that removes /tmp/restore_dir, /tmp/incr.tar.gz, /tmp/gz.tar.gz, /tmp/xz.tar.xz and echoes "cleaned". chmod +x and run. What is the output?', 100, '$2b$10$z8HQbpCQjCnQBlgGwNhWgewiFp7jAiS25938olMjKpQQaFqLgVGvG' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('434c3466-9de9-4e53-8463-58dd999fa07b', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Checksum Verifier', 'Run: sha256sum /tmp/backup.tar.gz | awk "{print $1}" | wc -c. How many characters is the SHA256 hash?', 75, '$2b$10$ht9mtZxYTgGM/rZBMME91.1eWTfAsCOC1th8dIIFNAmDwyAlRZjSO' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('e9808254-e0fa-4e34-9de5-e9c0a2bf0df6', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Date Stamped Backup', 'Run: tar czf /tmp/backup_$(date +%Y%m%d).tar.gz -C /home/student/backup_data . && ls /tmp/backup_*.tar.gz | wc -l. How many date-stamped backups?', 100, '$2b$10$y1WAkRqhXMMIviCt0hAu5OLxGaxVmTnmwqQwSo6kWTwydIL0fmTya' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ddfd9603-f6e1-48f7-a3df-8a2836d4c023', '884ee166-21d8-4336-a519-6ccdf111068c', 'iptables List', 'Run: iptables -L -n | head -3. What is the first chain name shown?', 50, '$2b$10$HAg3JX/b/XmsYQoqfXT5jeQCIj.M3s57EN8/I2Uf2KhIoylgpKrqS' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ceaa6245-1aa3-42c9-866b-565f1bb9ad95', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rule Creator', 'Run: iptables -A INPUT -p tcp --dport 8080 -j ACCEPT && iptables -L INPUT -n | grep 8080. What target is shown?', 75, '$2b$10$Y.JDazOxu1a2GBaVdBs4Y.PLXzjEZoq0YdcquoLluLNa6493r8BqC' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('484b5676-0bf7-4ce8-857f-5c8bb85ff1f2', '884ee166-21d8-4336-a519-6ccdf111068c', 'Port Blocker', 'Run: iptables -A INPUT -p tcp --dport 9999 -j DROP && iptables -L INPUT -n | grep 9999. What target?', 75, '$2b$10$9riANVPxcNzcGBHJCTGH/uu9rDxkmLP8rEvLLQt1b3YnHQSpcSXPq' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c75124f7-86eb-4634-bebb-7cb27a901934', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rule Deleter', 'Run: iptables -D INPUT -p tcp --dport 9999 -j DROP && iptables -L INPUT -n | grep -c 9999. How many rules for port 9999?', 100, '$2b$10$.XIT2.Y5.1n1c0oldNn1t.lV2idFZAWanGfZxtAI1gRIP1uscXps2' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('81c863a2-ca4a-4439-9bcf-f2a4759f4bb6', '884ee166-21d8-4336-a519-6ccdf111068c', 'Chain Creator', 'Run: iptables -N MYCHAIN && iptables -L | grep MYCHAIN. What chain name appears?', 100, '$2b$10$nAMKCgVFh1H8UIpwFX9Gd.DUrJ9ZErzYVVgX/jDb7zar0F45NeuSO' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('bdf39b3d-ba42-46ab-af31-829b2f306e27', '884ee166-21d8-4336-a519-6ccdf111068c', 'IP Blocker', 'Run: iptables -A INPUT -s 10.10.10.10 -j DROP && iptables -L INPUT -n | grep 10.10.10.10. What target?', 100, '$2b$10$NJkH3dWR4DfNyz8DlbwRB.FhJYxsCGSiBUYLYURQmaeTBJr4C3ABW' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f72d4bb9-b944-4620-afd9-367500ac0e0d', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rate Limiter', 'Run: iptables -A INPUT -p tcp --dport 80 -m limit --limit 10/min --limit-burst 20 -j ACCEPT && iptables -L INPUT -n | grep "limit:10/min". Is limit shown? (yes/no)', 100, '$2b$10$ObShJgChnk.NZkdnJjWT0OPDx1qbW9ymy8uZpdCslE/R5xZBWdafK' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('032fd640-a6b5-45dc-aef2-f8338c9c8bfb', '884ee166-21d8-4336-a519-6ccdf111068c', 'State Inspector', 'Run: iptables -A INPUT -m state --state ESTABLISHED,RELATED -j ACCEPT && iptables -L INPUT -n | grep ESTABLISHED. What states are listed?', 100, '$2b$10$opsBrybjBr8BNONnxcdcgOTRw/oExgangEDFbZ6tUb0uBESHBS8q6' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('185a64f8-febf-4c9f-b7c7-47fb970cbe95', '884ee166-21d8-4336-a519-6ccdf111068c', 'NAT Creator', 'Run: iptables -t nat -A PREROUTING -p tcp --dport 8080 -j REDIRECT --to-port 80 && iptables -t nat -L PREROUTING -n | grep 8080. What target?', 100, '$2b$10$mklKEdg2js24T9C9p4vft.T9jLNMtD0ozFKzF68y68e/y4I7Xir46' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('dbaece38-d105-451b-81f0-0e16204dadf3', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rule Saver', 'Run: iptables-save > /tmp/iptables_rules.txt && wc -l /tmp/iptables_rules.txt. How many lines of rules?', 100, '$2b$10$q66kvU7PljwGgQSzClzih.bjGzWOGhbisZXb6EwQzwAriRcXin4Aq' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('11c320aa-a603-46a5-ab12-0e7100a7d0f9', '884ee166-21d8-4336-a519-6ccdf111068c', 'Log Logger', 'Run: iptables -A INPUT -p tcp --dport 8080 -j LOG --log-prefix "FIREWALL: " && iptables -L INPUT -n | grep LOG. What log prefix is shown?', 100, '$2b$10$u1/qXIWFCOQNNZzAUX8LE.UOc9D8Kk1qEJvnjzgqK/0eNyGLZXCvC' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6bd9bdef-eda7-4545-a392-b25a52159d20', '884ee166-21d8-4336-a519-6ccdf111068c', 'Interface Binder', 'Run: iptables -A INPUT -i eth0 -j ACCEPT && iptables -L INPUT -n | grep eth0. What interface is shown?', 100, '$2b$10$fSQ4b5LiGffFE6FDGKhvSu/8YDKSaw81E2s6PqdTqTn8vk0x73Nx6' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('62112102-e12a-4c4c-95f4-dcacf647d9d6', '884ee166-21d8-4336-a519-6ccdf111068c', 'Packet Counter', 'Run: iptables -Z INPUT && iptables -L INPUT -v -n | head -3. What is the pkts count for INPUT chain?', 100, '$2b$10$W5g5d/oIE6N/5nJdZqKyduoN0iC4N4dL.4H3SQqj0rV.efRDVGxMq' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('cc06a613-96f9-4b57-a065-7e6d4956d8b6', '884ee166-21d8-4336-a519-6ccdf111068c', 'Flush Master', 'Run: iptables -F MYCHAIN && iptables -L MYCHAIN -n | wc -l. How many rules in MYCHAIN after flush?', 75, '$2b$10$o9ZI/LjxvQnbqHKuAYj3vuBurLc6RNArjWcNqzZB848V6HUQdfbpe' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ddc7a407-b2c6-41cc-afa3-64f7979a913a', '884ee166-21d8-4336-a519-6ccdf111068c', 'Cleanup', 'Run: iptables -F && iptables -X MYCHAIN 2>/dev/null; iptables -t nat -F PREROUTING 2>/dev/null; echo "firewall_done". What is the output?', 75, '$2b$10$.3VdNJ3xyXbt.CzuR112zOHFuhGvOSMVEAAJFE4gHwbEk.5wIFQ9C' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b00e5fed-4a99-4993-9fd4-0c6a19492dae', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Zone Creator', 'Create zone file: /etc/bind/zones/aeroacademy.local. Add SOA record for aeroacademy.local. Run: named-checkzone aeroacademy.local /etc/bind/zones/aeroacademy.local 2>&1 | tail -1. What is the status?', 75, '$2b$10$5Kh08D.sq5M3FcnM8zL/bucvI0IMGv9X5.I4tyhB4YnWVL8Dm27Uq' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('56f8ac63-b339-4fa6-8b5b-990c1ef9a4ec', 'e0decd06-4a2e-4f94-965a-79854928514d', 'A Record', 'Add A record: aeroacademy.local IN A 192.168.1.100. Run: grep "IN A" /etc/bind/zones/aeroacademy.local. What IP is shown?', 75, '$2b$10$YbedXuMooXZ1LmNerB/iPuz7c3WIiKEExL4KjoVVy/m1I1piEN35q' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('32244b8e-c56a-44a3-bc73-f88db98d6966', 'e0decd06-4a2e-4f94-965a-79854928514d', 'MX Record', 'Add MX record: aeroacademy.local IN MX 10 mail.aeroacademy.local. Run: dig MX aeroacademy.local +short. What is the mail server?', 100, '$2b$10$OIEp.wY4WpXCASyGaxWniu4ubsxWnfn1D430NxQ5BQCV6TH3JJB2G' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d572f49e-9059-45e3-a18c-8cbbe1f0ce02', 'e0decd06-4a2e-4f94-965a-79854928514d', 'CNAME Record', 'Add CNAME: www.aeroacademy.local IN CNAME aeroacademy.local. Run: dig www.aeroacademy.local +short. What does it resolve to?', 100, '$2b$10$WcPL8N6iMG3K7eGxsCGMk.ZVblMn27U8z4m/S6.tmnaobf4AIA8ym' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c771f6f3-38e5-4e3c-b932-3987970caf7a', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Reverse Zone', 'Create reverse zone for 1.168.192.in-addr.arpa. Add PTR: 100 IN PTR aeroacademy.local. Run: named-checkzone 1.168.192.in-addr.arpa /etc/bind/zones/reverse.local 2>&1 | tail -1. What status?', 100, '$2b$10$1lvYSTzwxsiYm3svpf2i4OYBlnDd3qG/bnMYawZkJGVhjeOSHAsMi' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('38607142-e6d7-4291-9d7a-df88c6befeb5', 'e0decd06-4a2e-4f94-965a-79854928514d', 'NS Record', 'Add NS record: aeroacademy.local IN NS ns1.aeroacademy.local. Run: dig NS aeroacademy.local +short. What nameserver is shown?', 100, '$2b$10$YYBeHMgATU0JuH0UEpdF5ecXznVp0hNV8AMsKsTR5j7J5E1vfdJNO' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0122783a-0919-4a93-a928-830e13a3b918', 'e0decd06-4a2e-4f94-965a-79854928514d', 'TXT Record', 'Add TXT record: aeroacademy.local IN TXT "v=spf1 mx -all". Run: dig TXT aeroacademy.local +short. What is the TXT value?', 100, '$2b$10$nYNErklp1CQxQahYM1iZr.TF/SC1AaF6CoxQHX5fC0NO5luM.ckkq' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5292237c-6d6c-4ce7-9a48-97b9750afb71', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Config Inspector', 'Run: cat /etc/bind/named.conf.local | grep "zone" | wc -l. How many zones are defined?', 75, '$2b$10$QeODyNxDPFN12jPm4fyiTum8yQUhu4jtVZFtkCm.FJdHmPd2me/E6' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('db29800b-0bb0-4798-b5c6-e7204721e426', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Serial Bumper', 'Update SOA serial to 2024010101. Run: grep serial /etc/bind/zones/aeroacademy.local | awk "{print $1}". What is the serial number?', 100, '$2b$10$0F0Ek8encax0py22lxcevOTjv9wZjjVnJvvJ/Q8zraxjmctYgUxh6' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('eff087e2-d494-4cf0-b876-ec54b49c1a41', 'e0decd06-4a2e-4f94-965a-79854928514d', 'TTL Set', 'Set TTL to 3600 in the zone file. Run: grep -m1 ";" /etc/bind/zones/aeroacademy.local | awk "{print $1}". What is the TTL?', 75, '$2b$10$.7p5S8a6JJHbRU11l1KXFe8uBKqm6TYckcwJfe55uN89ztzEbtCgy' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('cb493718-070b-4fe5-a2ef-6d6a2080e5dd', 'e0decd06-4a2e-4f94-965a-79854928514d', 'AAAA Record', 'Add AAAA record: aeroacademy.local IN AAAA ::1. Run: dig AAAA aeroacademy.local +short. What is the IPv6 address?', 100, '$2b$10$WGdbvR0vKSqenIrJhZcGe.qIQrwjSZiuGU2v2H9po9C2y08bgM78e' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('daab90a6-c7ce-4d78-95c2-35e7be073338', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Wildcard Record', 'Add wildcard: *.aeroacademy.local IN A 192.168.1.100. Run: dig random.aeroacademy.local +short. What IP resolves?', 100, '$2b$10$OoKOJkhr/7vk/lKHjSKaSO1zZADL/1NrwFvzX0Zu5fnLKYgf70iwK' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('e3be8298-2f57-4759-931f-cde86253cbda', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Config Validator', 'Run: named-checkconf /etc/bind/named.conf 2>&1. What is the output (empty means OK)?', 75, '$2b$10$HQ/PU0y4NbyAxmFU5B.pI.5xG0Z3cLQQOL4LiRnKRTrBrj3w5L3pq' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d13a44e6-9c9e-4c82-a1e1-d03603a0f98a', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Zone Dumper', 'Run: dig axfr aeroacademy.local @localhost 2>&1 | wc -l. How many lines in zone transfer?', 100, '$2b$10$jJBILn/2KdQqvZc6HGTi0OlwVdxlBVtMiK8ivfdq8inbQzkKigJIG' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c93df9b0-f554-41e8-8308-1d8614774a2e', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Cleanup', 'Run: systemctl stop named 2>/dev/null || service named stop 2>/dev/null; echo "dns_done". What is the output?', 75, '$2b$10$HJBeOYD5eUoIGytZ1kkl/.QKorceOgsWF9jJvYSNb1Q10GyTXVkZK' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('de81d6a7-d346-4aa0-bbbf-deb40d99ec8d', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Repo Creator', 'Run: mkdir /home/student/myrepo && cd /home/student/myrepo && git init. Run: ls -la /home/student/myrepo/.git/HEAD. What does it contain?', 50, '$2b$10$UtQ86XaZ71BH2bOIBaLIVOBgmlusZpmqqeeFkfQQynTjAumFpJp26' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('bb4e35ec-7ab9-42e6-9090-da2f5a48b351', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Commit Crafter', 'In myrepo, create file.txt with "hello git". Run: git add . && git commit -m "first". Run: git log --oneline | wc -l. How many commits?', 75, '$2b$10$SuASunBXz3qImrk5I37B9u3Erw0eOhHRzd6xFmZQFH3J8STTL/A4e' ON CONFLICT DO NOTHING);
