INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b188112e-7f58-4eac-a66f-6ebc2f7129f6', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Merge Pro', 'On feature branch, edit file.txt to "feature edit". Commit. Switch to main, merge feature. Run: git log --oneline | wc -l. How many commits now?', 100, '$2b$10$BKP.kMMVCSUTeu1tDgnKHeinCp2/EUjr5pLv5Z4m2ptjFOpTR2hwy' ON CONFLICT DO NOTHING);
