INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d8dbb69c-dec8-4c78-830f-3b3c244df182', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Remote Connector', 'Run: git remote add origin /tmp/remote.git && git remote -v | head -1. What URL is shown?', 100, '$2b$10$g9gZp2Fuh2pQ1MiuWxCgu.JdjtAQPRZ8TAXfQoasrs1q6hbR563OW' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('661bae6c-93d9-4142-abf7-9f158c77491f', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Blame Reader', 'Run: git blame file.txt | head -1. What commit hash is shown?', 100, '$2b$10$JuafmhgYIm2XBtXJaHdoO.VJ81TeTsfbjs4jRAH.RK5AAUirbCVMa' ON CONFLICT DO NOTHING);
