INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9e72b98b-5dd4-40ea-861f-8d822b668943', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Reset Master', 'Run: git reset HEAD~1 && git log --oneline | wc -l. How many commits after reset?', 100, '$2b$10$THFBtMR5U0YWazbWtrWwL.mn5m1wkKF3/7xVLj7njcsLGkeUR/Vi.' ON CONFLICT DO NOTHING);
