INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('e529e692-9806-422f-a563-f6d14bf18554', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Submodule Starter', 'Run: git submodule add /tmp/submod.git modules/sub 2>/dev/null; echo "submodule_done". What is the output?', 100, '$2b$10$0GHQRTDSOLag9pxwqtbYMejYEyOrRW/OfX7iQXsEX6hS0eTH0K1e.' ON CONFLICT DO NOTHING);
