INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('a82b6b22-43fe-45d8-b713-08b9052c1847', '19796c88-1a0a-4c0c-ba7d-4422edecb4fe', 'Cluster Cleanup', 'Run: kubectl delete namespace dev 2>&1 && echo "k8s_cleanup_done". What is the output?', 75, '$2b$10$ubrRGiexUCTaUccjSZom1.CuGVhl3D1reQQQU7BYVF2003y0W8Jsy' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('e17f899e-355a-4dba-a467-c711ddeeeb61', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Package Manager', 'Run: yum list installed 2>/dev/null | head -3 || dnf list installed 2>/dev/null | head -3 || echo "package_manager_available". What package manager is available?', 50, '$2b$10$gNNpQwi4hHzhoyJiArh30.PFaCN9hfXeoajAQX1ubzymBazeNOtjW' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6c6760cf-c5e8-46e8-898e-061af9338a83', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Service Control', 'Run: systemctl list-units --type=service 2>/dev/null | head -3 || service --status-all 2>&1 | head -3 || echo "services_listed". What services are shown?', 50, '$2b$10$M1Qa.Bi6Relbx3rGRd6lmuURIaqJqMsrtk.GifflHLb/lY/kv5rZe' ON CONFLICT DO NOTHING);
