INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5a96144a-45d7-4c9e-aada-1705bffd1af6', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Firewall Manager', 'Run: firewall-cmd --list-all 2>/dev/null || iptables -L -n 2>/dev/null | head -3 || echo "firewall_checked". What firewall is active?', 75, '$2b$10$YHcYnJmXTQLqpsNG/NULqOTZt76QHqBqVsN6G1WnTL9w0h7XMz/BC' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ef43180d-f127-4920-90c3-f503d9e8f55b', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Yum Repository', 'Create /etc/yum.repos.d/custom.repo with [custom], name=Custom, baseurl=http://example.com/repo, enabled=1. Run: cat /etc/yum.repos.d/custom.repo | grep "name=". What is the repo name?', 100, '$2b$10$nelIrpcmYS2BfZAbdM6xmeh5vRB3fIISq5fQOYjVG7BTyJDCyvt0a' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('81cb73a7-05d2-423c-89b6-53510f70dc9b', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Cron Master', 'Create cron: echo "0 2 * * * /usr/local/bin/backup.sh" | crontab -. Run: crontab -l | head -1. What is the schedule?', 100, '$2b$10$wciuuz59lUkQJzxa.KwlP.gmVbTu3OvkDHStwCyANUSHkpG8gFQ06' ON CONFLICT DO NOTHING);
