INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('aa392e24-ccd9-4dba-9af0-42f6072a8bcc', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'User Manager', 'Create user: useradd -m devuser && id devuser. What UID is assigned?', 100, '$2b$10$QcQaLAloP73aniO56EFjcuWo5YEKOGZZrnSp0VjOvs3ki0bm/ZA22' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('2f18c4b0-9857-4373-be28-09a6d647c070', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Tmpfiles Creator', 'Create /etc/tmpfiles.d/custom.conf with: d /run/custom 0755 root root -. Run: cat /etc/tmpfiles.d/custom.conf | head -1. What path is created?', 100, '$2b$10$ySN3I9TytkiO1P8hoQzkGegjOMmNpNaTJuE6x2X/9.ft2OWxCSrDm' ON CONFLICT DO NOTHING);
