INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('28546322-81ae-41bb-b1e5-938b8bda0ae6', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Disk Partitioner', 'Run: lsblk | head -3. What block devices are shown?', 75, '$2b$10$TSMzho.S8sSfkUdW1506JOYJ/fePK/Ya9TEF6RmAv6ns/EsXg7Ifa' ON CONFLICT DO NOTHING);
