INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f0a11c72-f42e-4dce-8e5a-f291d108271f', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'Process Inspector', 'Run: cat /proc/1/cmdline | tr "\0" " ". What command is PID 1 running?', 50, '$2b$10$CBngK9lWoFcuesclJmTnr.wDpM/ooBLYgrA.94YwAin2soirVHNiW' ON CONFLICT DO NOTHING);
