INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('fdf95871-397a-486e-9cac-95aebf6c9bcf', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'Date Formatter', 'Run: date +%Y%m%d. What is today date in YYYYMMDD format?', 75, '$2b$10$b1RCIZLpVoSsTMyqimKqAOkAE2q/PW3Bti8iJa8Zd04RDvfQ/Zl5u' ON CONFLICT DO NOTHING);
