INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8e41c301-1436-4032-b030-06e7cd4a8499', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Database Creator', 'Create a database called shopdb. Run: mysql -u root -e "SHOW DATABASES" | grep shopdb. What is the output?', 50, '$2b$10$YLJXj8wtihy5jxWqLdhdnuxeiZdw8jiSVf5Uu0v5rkaVrgtJgEKCK' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c73c3722-8c5d-4f0f-b336-aaa3b8116f58', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Table Architect', 'Create table products (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50), price DECIMAL(10,2), stock INT DEFAULT 0). Run: DESCRIBE products | wc -l. How many columns (minus 1 for header)?', 75, '$2b$10$VXvHJ7fnio4gG39EAOQi3u8avLZyi9LN1.TxYWBK..dkSfuBXvEEa' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ec111990-0f45-48c0-882f-ecdf02f3c40a', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Data Inserter', 'Insert into products: ("Laptop", 999.99, 10), ("Mouse", 29.99, 100). Run: SELECT COUNT(*) FROM products. How many rows?', 75, '$2b$10$0I4RZqLz3FYVWUROmU4y/Op9lraqv12dm02514MsU1GdFcIpgMWL2' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('32b72535-27c2-4ab5-b12f-75ad9efa3d71', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Query Master', 'Run: SELECT name FROM products WHERE price > 50 ORDER BY price DESC LIMIT 1. What product name?', 75, '$2b$10$XuL3187WnjV4tlCYjDz07.vbMM2IV3usGazO2wijTljqUBHJo13te' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('75ca4686-78e6-46c2-9a4c-b26d3b203a01', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Index Builder', 'Create index on products(name). Run: SHOW INDEX FROM products WHERE Key_name != "PRIMARY" | wc -l. How many non-primary indexes?', 100, '$2b$10$Xtg6PSZ2HfsMWFlYUcAIquoEDYBAWPU3/6VRR9Q7/VY685Dl.9D42' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('94aaf4e5-8ad5-44e0-acba-ae02ccadd718', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'User Manager', 'Create user "appuser"@"localhost" identified by "secret123". Grant SELECT,INSERT on shopdb.*. Run: SHOW GRANTS FOR "appuser"@"localhost" | grep "ON shopdb.*". What privileges are shown?', 100, '$2b$10$t.8ZGjjpxrWRDzhEhtET1.6jugF9x88hyF.CPoifOs8BYpWxhVV96' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('513a5672-2737-450b-a6f8-1a7aad2e3a25', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Backup Creator', 'Run: mysqldump -u root shopdb > /tmp/backup.sql && wc -l /tmp/backup.sql. How many lines in the backup file?', 100, '$2b$10$BHfun.zLeCoq3xAs5znA4.iZ7IYlfUnW6lMnI3qARTyiTQBuAlwQC' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c6e055c3-185d-4476-8ed1-a52ff4a646df', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Join Artist', 'Create table orders (id INT PRIMARY KEY AUTO_INCREMENT, product_id INT, quantity INT, FOREIGN KEY (product_id) REFERENCES products(id)). Insert 2 orders. Run: SELECT p.name, o.quantity FROM products p JOIN orders o ON p.id=o.product_id | wc -l. How many result rows (minus header)?', 100, '$2b$10$plsWD3k8t/qAu.lO7ndpnOy4V9AB1RwD3bhWeBo4oQPiqSBSoIW0G' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('bd22da28-ffe5-443d-82f1-3e0c6c90c1f0', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Aggregation Expert', 'Run: SELECT SUM(price * stock) as inventory_value FROM products. What is the total inventory value?', 100, '$2b$10$YyffI/1m6ZGwLxqOqTCdeuRqbJ9QfXQ3/fuerMYTas4jNt30IbynK' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8bc77de0-d028-4571-bb35-4f566a40e162', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Transaction Tester', 'Run: mysql -u root shopdb -e "START TRANSACTION; UPDATE products SET stock=stock-1 WHERE name=''Laptop''; COMMIT;" && mysql -u root shopdb -e "SELECT stock FROM products WHERE name=''Laptop''". What is the stock?', 100, '$2b$10$ujnHbM7JJkah5VVORJRJ2.AiQ0V5SQVYPrqtLhc2VPPGAvbbaHvY2' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('47f8114e-3b6e-4b14-918c-92047fe489b9', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'View Creator', 'Create view cheap_products as SELECT name, price FROM products WHERE price < 50. Run: SELECT * FROM cheap_products. What product appears?', 100, '$2b$10$4GNgTq3s04EFM3q/ELdfAuPjp4L0vzE1qGe4rxdQq9guAzyvy1omu' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b92b823e-1ec1-4053-b297-27beb06eb161', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Permission Auditor', 'Run: mysql -u root -e "SELECT user FROM mysql.user" | grep appuser. What user is listed?', 75, '$2b$10$rsaSfuuS63TZduDzUaXC1ukVYnxsPyFho6c3hRhgpmn5HMNxBXOzO' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6e063b58-413c-4dc4-b679-653ed21ccc65', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Schema Inspector', 'Run: mysql -u root shopdb -e "SHOW TABLES" | wc -l. How many tables exist (minus header)?', 75, '$2b$10$YJ.iBmrYfHgECsWGN/Lt4eYICqk7B7KTA8tDDWSiw/YtBtozUDU/W' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('db003a3b-cc73-44fa-9bee-92afffafe292', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Auto Increment Expert', 'Insert 3 more products. Run: SELECT MAX(id) FROM products. What is the highest id?', 100, '$2b$10$3RpjQawzRb6pbXbKQGRO/.Kt.H3Sz3v4Sobxnfj1sfjCK.UkSzDrC' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9ad41284-9df1-430b-8d89-7ace72156972', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Data Updater', 'Run: UPDATE products SET price=price*1.1 WHERE name="Mouse" && mysql -u root shopdb -e "SELECT price FROM products WHERE name=''Mouse''". What is the new price (rounded to 2 decimals)?', 100, '$2b$10$4IAgT.9zDOk1YrfBG3Hx1O7d6db6K9gWnvDMNItnM61lp8Kq6hf/K' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('3c8c42e0-e195-4578-8a2e-40154954b5e0', '50d6a493-7898-473d-8287-137229593da9', 'Virtual Host Builder', 'Create /etc/nginx/sites-available/mysite.conf with a server block listening on port 9090, root /var/www/mysite. Create /var/www/mysite/index.html with "Hello Custom". Enable the site with ln -s and reload nginx. Run: curl -s localhost:9090. What is the content?', 100, '$2b$10$a.tiy6iN70/TLjbpisYbtOf.DoeTBm7VbUNb78RhaqDR920OkvYAi' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('619f1bd3-e722-4007-aec4-137f38344482', '50d6a493-7898-473d-8287-137229593da9', 'Reverse Proxy', 'Start a python http server on port 8888: python3 -m http.server 8888 &. Create nginx reverse proxy config on port 9091 proxying to localhost:8888. Reload nginx. Run: curl -s localhost:9091. What HTML title is shown?', 100, '$2b$10$ngocGQm59FgIRVRId9rtHueWQpmlpCMMTDVJo43HF9/cjFoyRLm.K' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c6274e94-7eef-4a03-a8e2-1171fd72a143', '50d6a493-7898-473d-8287-137229593da9', 'SSL Generator', 'Create /etc/nginx/ssl/ directory. Generate self-signed cert: openssl req -x509 -nodes -days 365 -newkey rsa:2048 -keyout /etc/nginx/ssl/key.pem -out /etc/nginx/ssl/cert.pem -subj "/CN=localhost". Run: openssl x509 -in /etc/nginx/ssl/cert.pem -noout -subject. What is the CN value?', 100, '$2b$10$nGbY2l2fRgSgyl6xAb9LeOTD0lM4P5v9cH07ouy9pYjuCUmGjBNTi' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('99eecd27-1198-4bf3-9430-bd8900215115', '50d6a493-7898-473d-8287-137229593da9', 'Rate Limiter', 'Add to your nginx server config: limit_req_zone $binary_remote_addr zone=one:10m rate=1r/s;. Then add limit_req zone=one burst=5 nodelay to a location block. Reload. Run: for i in 1 2 3 4 5 6; do curl -s -o /dev/null -w "%{http_code} " localhost:9090; done. What HTTP codes appear (space-separated)?', 100, '$2b$10$MnXikUp08aDWXXGdqjX4zuVzQ7JTsN9AA9lTSoIOUZ/4CniUrCAb.' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('afb262b4-1c84-4e5a-b55c-932df45f20f0', '50d6a493-7898-473d-8287-137229593da9', 'Gzip Optimizer', 'Add gzip on; gzip_types text/plain; to the http block in /etc/nginx/nginx.conf. Reload nginx. Run: curl -s -H "Accept-Encoding: gzip" -D - localhost 2>&1 | grep -i content-encoding. What encoding is shown?', 100, '$2b$10$CuRowPGjOdmJ7lxXmP3u0eS5rhIT52jYJbWYaT/TYyFAwuvK9RmbO' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('37151021-3a84-4740-9c23-29e372d99690', '50d6a493-7898-473d-8287-137229593da9', 'Load Balancer', 'Start 2 python servers on ports 8889 and 8890 (python3 -m http.server 8889 & and python3 -m http.server 8890 &). Create nginx upstream config on port 9092 load balancing between them. Reload and curl localhost:9092. What is the upstream block name you used?', 100, '$2b$10$HT62Jvp8LcDw2wqVgHa2fuPPDp1dMiVJJBoKV2ALsDIMNr90oPlfO' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('a507e00d-3b53-40bd-8c5e-5f2279ea0496', '50d6a493-7898-473d-8287-137229593da9', 'Access Control', 'Create a location block for /private with "allow 127.0.0.1; deny all;". Reload nginx. Run: curl -s -o /dev/null -w "%{http_code}" localhost:9090/private. What status code?', 100, '$2b$10$PlUsQIUm1p/sjwkYIecfbOv/eBFqLBpj/kePAJ2ITfmmFvVluztRC' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('2951c68d-b02d-4daf-a685-79664f565066', '50d6a493-7898-473d-8287-137229593da9', 'Error Page Customizer', 'Create /var/www/mysite/404.html with "Page Not Found". Add error_page 404 /404.html to your server block. Reload. Run: curl -s localhost:9090/nonexistent. What is the content?', 100, '$2b$10$PbeS86xayhjfCpaFKCIf/edsMSB2f0QihiVPHiF7hSbjXrmpyEEei' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5ef9703b-dd93-4b1b-ae5a-ebc5a8083b33', '50d6a493-7898-473d-8287-137229593da9', 'Log Analyzer', 'Make 5 requests to nginx. Then run: cat /var/log/nginx/access.log | tail -5 | wc -l. How many access log entries?', 75, '$2b$10$tE8M1fqkqEswIu6qckG6YeRlZT0FmqcZP4H19FunHlHWUQtv0QnTa' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c05c3aaa-2dc7-4ec0-92eb-9d04fe4c7761', '50d6a493-7898-473d-8287-137229593da9', 'Rewrite Master', 'Add to your server config: location /old { return 301 /new; }. Create /var/www/mysite/new.html with "Redirected". Reload. Run: curl -s localhost:9090/old. What is the content after redirect?', 100, '$2b$10$ZA9cFcqeuIj4ms7i0PcWp.3gh3xMv7mZjM7.UfvxDWvmyzn4gxAZy' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c1f1e115-d3f4-45ac-b80b-97ac8a793e96', '88de7b45-d1c8-4d13-97df-66805199f591', 'Database Creator', 'Create database shopdb using createdb. Run: psql -l | grep shopdb. What is the output?', 50, '$2b$10$/jYQROl8zhL.WeRX7dLCMesgEBGEg281IvkAiCInLz2g/1lsIx71.' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('565cdfac-7633-4a67-b9f1-801d8b595301', '88de7b45-d1c8-4d13-97df-66805199f591', 'Table Architect', 'Create table products (id SERIAL PRIMARY KEY, name VARCHAR(50), price NUMERIC(10,2), stock INT DEFAULT 0). Run: \d products | wc -l. How many lines of column info?', 75, '$2b$10$Ahw42CLyrIsTuoOvJvDqd.euAwH5fxeXL1BQOGh1oOZSZ9ukc0dr6' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('4462a6a4-f3a5-4ebf-8374-a9da544b434b', '88de7b45-d1c8-4d13-97df-66805199f591', 'Data Inserter', 'Insert into products: ("Laptop", 999.99, 10), ("Mouse", 29.99, 100). Run: SELECT COUNT(*) FROM products. How many rows?', 75, '$2b$10$rzmpOJFDsqWg0ASFL4JaW.pDy2POGHtcZZYpK7Rh8fq8Y4g2JizuO' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f05ffd85-e0af-49b1-9a64-5b818447471c', '88de7b45-d1c8-4d13-97df-66805199f591', 'Query Master', 'Run: SELECT name FROM products WHERE price > 50 ORDER BY price DESC LIMIT 1. What product?', 75, '$2b$10$GYZ7KTgZFCHlP0YQdUYIr.LOiHS6AavcZRgRWAq5t6ktoGvAIR5Q6' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c57695ef-229f-4a53-9745-af87dbee40b5', '88de7b45-d1c8-4d13-97df-66805199f591', 'Index Builder', 'Create index idx_products_name on products(name). Run: \di | grep idx_products_name. What index name is shown?', 100, '$2b$10$MjBiYolu9b3Apeorgjijau4KTyNsfcdsgpXRvjaEV4ssxxHJXnmai' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f6548570-ff5e-41a1-b4d5-6641e7db07ec', '88de7b45-d1c8-4d13-97df-66805199f591', 'Role Manager', 'Create role appuser LOGIN PASSWORD ''secret123''; Grant CONNECT on shopdb to appuser. Run: \du | grep appuser. What is listed?', 100, '$2b$10$gVSHSk62FxLyzlXolIMDRe1ee6unCxhMdTKLvLYQwx5PXyj6P8XS2' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9bec8a9e-9ed1-4bd0-819f-49026dcf4119', '88de7b45-d1c8-4d13-97df-66805199f591', 'Backup Creator', 'Run: pg_dump shopdb > /tmp/pgbackup.sql && wc -l /tmp/pgbackup.sql. How many lines?', 100, '$2b$10$nINAr15LpSb45OHa8qweUerZxZx0.lLLc3XwHhqkaQiF.TIMm346q' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('95fee298-9130-4e82-9089-4ea0f2945f05', '88de7b45-d1c8-4d13-97df-66805199f591', 'Join Artist', 'Create table orders (id SERIAL PRIMARY KEY, product_id INT REFERENCES products(id), quantity INT). Insert 2 orders. Run: SELECT p.name, o.quantity FROM products p JOIN orders o ON p.id=o.product_id. How many rows (excluding header)?', 100, '$2b$10$zrSLTZkZSx4w5diJYml7DuUnPJgicpyzKxtvT5Js861MWVEwWLQ6W' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b7c29f2d-148d-420e-b5d9-6b333335fda2', '88de7b45-d1c8-4d13-97df-66805199f591', 'Aggregation Expert', 'Run: SELECT SUM(price * stock) as inventory_value FROM products. What is the total?', 100, '$2b$10$1zqy5ZwMf8m2cmfnjpyKM.TG55C2xaKctdCW8a758ZwBKC2jnq9MS' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9f77914b-4666-47bc-8b0c-d0c2cdc8ceae', '88de7b45-d1c8-4d13-97df-66805199f591', 'Transaction Tester', 'Run: psql shopdb -c "BEGIN; UPDATE products SET stock=stock-1 WHERE name=''Laptop''; COMMIT;" && psql shopdb -c "SELECT stock FROM products WHERE name=''Laptop''". What is the stock?', 100, '$2b$10$0D7lj6fylYeANk2c/06rxujqasgdDxrzyQski95h34tsl3/KjKAkS' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6a3ba7dc-c4f6-43b8-a396-3d123fb3fa23', '88de7b45-d1c8-4d13-97df-66805199f591', 'View Creator', 'Create view cheap_products AS SELECT name, price FROM products WHERE price < 50. Run: SELECT * FROM cheap_products. What product?', 100, '$2b$10$PMGyIswuoJC0WM1e3dkgEuWUB2uzeBTnEnHq7Ck4.ACZ1OSyg/jr6' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('bf832198-abdb-4855-bb15-a81cee64256f', '88de7b45-d1c8-4d13-97df-66805199f591', 'Permission Auditor', 'Run: psql -c "SELECT has_table_privilege(''appuser'', ''products'', ''SELECT'')". What is the result?', 75, '$2b$10$OU531LspzBxxQnJehV7cGOXYxsckcxEe84ZSStbuSaXW.bgnPGGia' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0c5df254-2b95-4378-8392-5fcdc395387e', '88de7b45-d1c8-4d13-97df-66805199f591', 'Schema Inspector', 'Run: psql shopdb -c "\dt" | grep -c "product". How many tables match?', 75, '$2b$10$i1Sa0O3SvC/rlQ9ve/N/UupKlKHxVB72IPQYLMMH8AJRf/l4rFK8e' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c53a4750-dfce-459c-a945-9b740ce39974', '88de7b45-d1c8-4d13-97df-66805199f591', 'Serial Expert', 'Insert 3 more products. Run: SELECT MAX(id) FROM products. What is the highest id?', 100, '$2b$10$j8mNzIq4bTzavFAF7tQuCOoZW2duINp74Qb4Y.q/u5ipabNt4olPe' ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8cf04d24-927a-4cda-baf3-7764d9372922', '88de7b45-d1c8-4d13-97df-66805199f591', 'Data Updater', 'Run: UPDATE products SET price=price*1.1 WHERE name=''Mouse'' and SELECT price FROM products WHERE name=''Mouse''. What is the new price (rounded to 2 decimals)?', 100, '$2b$10$gymVSWlqKaCX3axv.XnrXucJUYdBCdy.etCLAhU.ENGqNFbJ.UkBe' ON CONFLICT DO NOTHING);
